// Skip weekends + Friday — return empty so no work happens Fri/Sat/Sun
const day = new Date().getUTCDay();
if (day === 0 || day === 5 || day === 6) return [];
return $input.all();

// Flatten paginated Twenty responses -> one item per Person, mapped to flat fields
const out = [];
for (const item of $input.all()) {
  const body = item.json || {};
  const people = (body.data && body.data.people) ? body.data.people
               : (Array.isArray(body) ? body : []);
  for (const p of people) {
    if (!p || !p.id) continue;
    out.push({ json: {
      person_id: p.id,
      first_name: (p.name && p.name.firstName) || '',
      last_name: (p.name && p.name.lastName) || '',
      email: (p.emails && p.emails.primaryEmail) || '',
      org_name: (p.company && p.company.name) || '',
      job_title: p.jobTitle || '',
      fund_size: p.fundSize || '',
      timezone: p.timezone || '',
      stage: p.stage || 'COLD_LEAD',
      last_email_sent: p.lastEmailSent || ''
    }});
  }
}
return out;

// Stage filter already limits to COLD_LEAD / EMAIL_1_SENT.
// Send only if never emailed OR >= 72h since the last email.
const THREE_DAYS = 259200000;
const now = Date.now();
const out = [];
for (const item of $input.all()) {
  const d = item.json;
  const last = d.last_email_sent ? new Date(d.last_email_sent).getTime() : 0;
  if (!last || (now - last) >= THREE_DAYS) out.push(item);
}
return out;

// Only send during each contact's local window. Unknown/blank timezone => always passes.
// Set BYPASS = true to ignore timezones entirely (useful for testing).
const BYPASS = false;
if (BYPASS) return $input.all();
const timezoneWindows = { '28':9,'29':8,'30':14,'31':17,'32':5,'38':15,'39':3,'40':1,'41':0,'42':23,'43':7,'44':12,'45':13 };
const currentHourUTC = new Date().getUTCHours();
const results = [];
for (const item of $input.all()) {
  const tz = String(item.json.timezone || '');
  const sendHour = timezoneWindows[tz];
  if (sendHour === undefined || sendHour === currentHourUTC) results.push(item);
}
return results;

