// One item per approved contact, ready to send
const out = [];
for (const item of $input.all()) {
  const body = item.json || {};
  const people = (body.data && body.data.people) ? body.data.people : [];
  for (const p of people) {
    if (!p || !p.id) continue;
    const email = (p.emails && p.emails.primaryEmail) || '';
    if (!email) continue;
    out.push({ json: {
      person_id: p.id,
      to_email: email,
      subject: p.aiDraftSubject || 'Re: our conversation',
      body: p.aiDraftBody || ''
    }});
  }
}
return out;

// Take ONE unanalyzed Deal-stage contact per run (deals are infrequent)
const out = [];
for (const item of $input.all()) {
  const people = ((item.json || {}).data || {}).people || [];
  for (const p of people) {
    if (!p || !p.id || p.dealAnalyzed === true) continue;
    const email = (p.emails && p.emails.primaryEmail) || '';
    if (!email) continue;
    out.push({ json: { person_id: p.id, email,
      first_name: (p.name && p.name.firstName) || '',
      last_name: (p.name && p.name.lastName) || '' } });
    break;
  }
  if (out.length) break;
}
return out.slice(0, 1);

// Build the conversation text for the AI from this contact's Twenty notes
const deal = $('Pick One Deal').first().json;
const body = $input.first().json || {};
const targets = (body.data && body.data.noteTargets) ? body.data.noteTargets : [];
const notes = targets.map(t => t.note).filter(Boolean);
notes.sort((a,b)=> new Date(a.createdAt||0) - new Date(b.createdAt||0));
const text = notes.map(n => (n.title||'') + '\n' + ((n.bodyV2 && n.bodyV2.markdown) || '')).join('\n\n-----\n\n');
return [{ json: {
  person_id: deal.person_id, first_name: deal.first_name, last_name: deal.last_name,
  email: deal.email, thread_text: text || '(no conversation notes found for this contact)'
} }];

// Email-2-sent contacts with no reply for >= 7 days -> Done
const SEVEN_DAYS = 7 * 24 * 60 * 60 * 1000;
const now = Date.now();
const out = [];
for (const item of $input.all()) {
  const people = ((item.json || {}).data || {}).people || [];
  for (const p of people) {
    if (!p || !p.id) continue;
    const last = p.lastEmailSent ? new Date(p.lastEmailSent).getTime() : 0;
    if (last && (now - last) >= SEVEN_DAYS) out.push({ json: { person_id: p.id } });
  }
}
return out;
